#include "icon_packs.hpp"
#include <sstream>
#include <iomanip>
#include <set>
namespace aether::win {
namespace {
bool identifier(std::string_view s){return !s.empty()&&s.size()<=64&&s.find_first_not_of("abcdefghijklmnopqrstuvwxyz0123456789-")==s.npos;}
bool regular(const std::filesystem::path& p){const auto a=GetFileAttributesW(p.c_str());return a!=INVALID_FILE_ATTRIBUTES&&!(a&(FILE_ATTRIBUTE_REPARSE_POINT|FILE_ATTRIBUTE_DIRECTORY));}
bool safeDirectory(std::filesystem::path p){if(!p.is_absolute())return false;for(;!p.empty();){auto a=GetFileAttributesW(p.c_str());if(a==INVALID_FILE_ATTRIBUTES||(a&FILE_ATTRIBUTE_REPARSE_POINT))return false;auto next=p.parent_path();if(next==p)break;p=next;}return true;}
}
std::string iconAlias(std::string_view s){std::string out;for(unsigned char c:s)if((c>='a'&&c<='z')||(c>='0'&&c<='9'))out+=static_cast<char>(c);else if(c>='A'&&c<='Z')out+=static_cast<char>(c+32);return out;}
std::optional<IconPack> readIconPack(const std::filesystem::path& file,std::string* error){
 auto fail=[&](const char* why)->std::optional<IconPack>{if(error)*error=why;return {};};
 try{if(!regular(file)||!safeDirectory(file.parent_path()))return fail("Pack must be in a regular local directory without links.");auto text=readText(file,65536);std::istringstream input(text);std::string line;if(!std::getline(input,line))return fail("Empty icon pack.");if(!line.empty()&&line.back()=='\r')line.pop_back();if(line!="AetherIcons1")return fail("Expected AetherIcons1 header.");IconPack pack;pack.directory=file.parent_path();std::set<std::string> fields;
 while(std::getline(input,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty())continue;std::istringstream row(line);std::string key,value,asset,extra;if(!(row>>key>>std::quoted(value)))return fail("Malformed icon pack row.");if(key=="icon"){if(!(row>>std::quoted(asset))||!identifier(value)||pack.icons.size()>=512||!pack.icons.emplace(value,asset).second)return fail("Invalid or duplicate icon alias.");if(asset.empty()||asset.size()>100||asset.find_first_not_of("abcdefghijklmnopqrstuvwxyz0123456789-_.")!=asset.npos||asset.find("..")!=asset.npos||std::filesystem::path(asset).extension()!=L".png")return fail("Icons must be flat PNG filenames.");if(!regular(pack.directory/asset)||std::filesystem::file_size(pack.directory/asset)>1024*1024)return fail("Missing, linked or oversized icon asset.");}else{if(!fields.insert(key).second)return fail("Duplicate pack field.");if(value.size()>512||value.find_first_of("\r\n")!=value.npos)return fail("Invalid pack metadata.");if(key=="id")pack.id=value;else if(key=="name")pack.name=value;else if(key=="source")pack.source=value;else if(key=="license")pack.license=value;else return fail("Unknown icon pack field.");}if(row>>extra)return fail("Unexpected pack data.");}
 if(!identifier(pack.id)||pack.name.empty()||pack.name.size()>100||pack.license.empty()||pack.icons.empty())return fail("Pack needs an id, name, license and icons.");std::uintmax_t bytes=0;std::set<std::string> assets;for(const auto& [alias,asset]:pack.icons){(void)alias;if(assets.insert(asset).second)bytes+=std::filesystem::file_size(pack.directory/asset);}if(bytes>32*1024*1024)return fail("Pack exceeds 32 MiB.");if(error)error->clear();return pack;
 }catch(...){return fail("Could not read bounded local icon pack.");}
}
std::vector<IconPack> iconPacks(){std::vector<IconPack> out;for(const auto& root:{executablePath().parent_path()/L"assets"/L"icon-packs",configDirectory()/L"icon-packs"}){if(!safeDirectory(root))continue;std::error_code ec;int visited=0;for(const auto& e:std::filesystem::directory_iterator(root,ec)){if(++visited>64||out.size()>=32)break;if(ec)break;if(auto pack=readIconPack(e.path()/L"pack.aethericons")){if(std::none_of(out.begin(),out.end(),[&](const auto& p){return p.id==pack->id;}))out.push_back(std::move(*pack));}}}std::sort(out.begin(),out.end(),[](const auto& a,const auto& b){return a.name<b.name;});return out;}
std::optional<std::string> importIconPack(const std::filesystem::path& file,std::string* error){auto pack=readIconPack(file,error);if(!pack)return {};try{auto root=configDirectory()/L"icon-packs";std::filesystem::create_directories(root);if(!safeDirectory(root))throw std::runtime_error("Linked pack directory");auto target=root/pack->id;const auto installed=iconPacks();if(std::filesystem::exists(target)||std::any_of(installed.begin(),installed.end(),[&](const auto& p){return p.id==pack->id;})){if(error)*error="A pack with that id is already installed.";return {};}if(iconPacks().size()>=32){if(error)*error="Icon library is full (32 packs).";return {};}std::filesystem::create_directory(target);try{std::set<std::string> copied;for(const auto& [alias,asset]:pack->icons){(void)alias;if(copied.insert(asset).second)std::filesystem::copy_file(pack->directory/asset,target/asset);}for(const auto* name:{L"LICENSE.txt",L"SOURCE.txt"})if(regular(pack->directory/name)&&std::filesystem::file_size(pack->directory/name)<=131072)std::filesystem::copy_file(pack->directory/name,target/name);writeAtomic(target/L"pack.aethericons",readText(file,65536));if(!readIconPack(target/L"pack.aethericons"))throw std::runtime_error("Imported pack did not validate");}catch(...){std::filesystem::remove_all(target);throw;}if(error)error->clear();return pack->id;}catch(...){if(error)*error="Could not import the local pack.";return {};}}
std::filesystem::path packIcon(const IconPack& pack,const Pin& pin){for(const auto& value:{pin.identity,pin.name,utf8(std::filesystem::path(wide(pin.target)).stem().wstring())}){auto alias=iconAlias(value);auto it=pack.icons.find(alias);if(it!=pack.icons.end())return pack.directory/it->second;}return {};}
}
